Nullable ValuesDict LookupFirst Element <pre><code>def find_user(id: int) -&gt; Option&lt;str&gt;:
    if id == 1:
        return Option.Some("Alice")
    return Option.Nothing
</code></pre> <pre><code>def get_value(key: str, dict: dict[str, int]) -&gt; Option&lt;int&gt;:
    if key in dict:
        return Option.Some(dict[key])
    return Option.Nothing
</code></pre> <pre><code>def first&lt;T&gt;(items: list&lt;T&gt;) -&gt; Option&lt;T&gt;:
    if len(items) &gt; 0:
        return Option.Some(items[0])
    return Option.Nothing
</code></pre>

DivisionFile OperationsParsing <pre><code>def divide(a: int, b: int) -&gt; Result&lt;int, str&gt;:
    if b == 0:
        return Result.Err("Division by zero")
    return Result.Ok(a / b)
</code></pre> <pre><code>def read_file(path: str) -&gt; Result&lt;str, str&gt;:
    let file = open(path, "r")
    if file.is_open():
        return Result.Ok(file.read())
    return Result.Err(f"Cannot open {path}")
</code></pre> <pre><code>def parse_int(s: str) -&gt; Result&lt;int, str&gt;:
    if len(s) == 0:
        return Result.Err("empty input")
    return Result.Ok(int(s))
</code></pre>

